add_action( 'transition_post_status', static function ( $new_status, $old_status, $post ) {
    if ( 'publish' !== $new_status || $new_status === $old_status || 'revision' === $post->post_type ) {
        return;
    }
    $log = get_option( 'wpbp_pl_first_publish_log', array() );
    if ( ! is_array( $log ) ) {
        $log = array();
    }
    $log[] = (int) $post->ID;
    update_option( 'wpbp_pl_first_publish_log', $log );
}, 10, 3 );

function wpbp_posts_lifecycle_002( string $title, array $genre_term_ids ): int {
    $post_id = wp_insert_post(
        array(
            'post_title'   => wp_slash( $title ),
            'post_status'  => 'publish',
            'post_content' => '',
        )
    );
    if ( is_wp_error( $post_id ) || ! $post_id ) {
        return 0;
    }
    wp_set_post_terms( (int) $post_id, array_map( 'intval', $genre_term_ids ), 'wpbp_pl_genre' );
    return (int) $post_id;
}

function wpbp_posts_lifecycle_003( int $acting_user_id, string $html ): int {
    wp_set_current_user( $acting_user_id );
    kses_remove_filters();
    $post_id = wp_insert_post(
        array(
            'post_title'   => 'WPBP import',
            'post_status'  => 'publish',
            'post_content' => wp_slash( $html ),
        )
    );
    kses_init_filters();
    return is_wp_error( $post_id ) ? 0 : (int) $post_id;
}

function wpbp_posts_lifecycle_004( int $post_id ): string {
    add_filter( 'wp_untrash_post_status', 'wp_untrash_post_set_previous_status', 10, 3 );
    wp_untrash_post( $post_id );
    remove_filter( 'wp_untrash_post_status', 'wp_untrash_post_set_previous_status', 10 );
    return (string) get_post_status( $post_id );
}

function wpbp_posts_lifecycle_005( string $title, string $utc_datetime ): int {
    $post_id = wp_insert_post(
        array(
            'post_title'    => wp_slash( $title ),
            'post_content'  => 'scheduled',
            'post_status'   => 'future',
            'post_date'     => get_date_from_gmt( $utc_datetime ),
            'post_date_gmt' => $utc_datetime,
        )
    );
    return is_wp_error( $post_id ) ? 0 : (int) $post_id;
}

function wpbp_posts_lifecycle_006( int $post_id, string $post_date ): string {
    wp_update_post(
        array(
            'ID'        => $post_id,
            'post_date' => $post_date,
            'edit_date' => true,
        )
    );
    return (string) get_post_field( 'post_date', $post_id, 'raw' );
}

function wpbp_posts_lifecycle_009( int $post_id, bool $permanently ): bool {
    if ( $permanently ) {
        return (bool) wp_delete_post( $post_id, true );
    }
    return (bool) wp_trash_post( $post_id );
}

function wpbp_posts_lifecycle_010( string $path, string $post_type ): int {
    $post = get_page_by_path( $path, OBJECT, $post_type );
    return $post instanceof WP_Post ? (int) $post->ID : 0;
}

function wpbp_pl_011_first_sentence( string $content ): string {
    $text = trim( wp_strip_all_tags( $content ) );
    if ( '' === $text ) {
        return '';
    }
    $stop = strpos( $text, '.' );
    return false === $stop ? $text : trim( substr( $text, 0, $stop + 1 ) );
}

function wpbp_pl_011_sync_excerpt( $post_id, $post ) {
    static $running = false;
    if ( $running || 'revision' === $post->post_type || wp_is_post_autosave( $post_id ) ) {
        return;
    }
    if ( '' !== trim( (string) $post->post_excerpt ) ) {
        return;
    }
    $excerpt = wpbp_pl_011_first_sentence( (string) $post->post_content );
    if ( '' === $excerpt ) {
        return;
    }
    $running = true;
    wp_update_post(
        array(
            'ID'           => $post_id,
            'post_excerpt' => wp_slash( $excerpt ),
        )
    );
    $running = false;
}
add_action( 'save_post', 'wpbp_pl_011_sync_excerpt', 10, 2 );

function wpbp_posts_lifecycle_012( string $title ): string {
    $post_id = wp_insert_post(
        array(
            'post_title'   => wp_slash( $title ),
            'post_content' => '',
            'post_status'  => 'publish',
        )
    );
    if ( is_wp_error( $post_id ) || ! $post_id ) {
        return '';
    }
    return (string) get_post_field( 'post_name', $post_id, 'raw' );
}
